"use client";
const require_use_hotkeys = require("./use-hotkeys.cjs");
//#region src/providers/hotkeys/use-hotkey.ts
var useHotkey = (props) => {
	const { store, ...command } = props;
	require_use_hotkeys.useHotkeys({
		commands: [command],
		store
	});
};
//#endregion
exports.useHotkey = useHotkey;
